12	import { ContentHeroComponent } from 'components';
13	import {
14	    ExternalPlayerSession,
15	    ResolvedPortalPlayback,
16	    VodDetailsItem,
17	    getVodNumericId,
18	    normalizeVodDetails,
19	} from 'shared-interfaces';
20	import { DownloadsService } from 'services';
21	import { PortalInlinePlayerComponent } from '../portal-inline-player/portal-inline-player.component';
22	
23	/**
24	 * Unified VOD details component for both Xtream and Stalker portals.
25	 *
26	 * Uses discriminated union (VodDetailsItem) for type-safe handling.
27	 * All actions are emitted as outputs - parent components handle
28	 * store-specific operations (play, favorites, downloads).
29	 *
30	 * @example
31	 * ```html
32	 * <app-vod-details
33	 *   [item]="vodItem"
34	 *   [isFavorite]="isFavorite()"
35	 *   [playbackPosition]="position()"
36	 *   (playClicked)="onPlay($event)"
37	 *   (resumeClicked)="onResume($event)"
38	 *   (favoriteToggled)="onToggleFavorite($event)"
39	 * />
40	 * ```
41	 */
42	@Component({
43	    selector: 'app-vod-details',
44	    templateUrl: './vod-details.component.html',
45	    styleUrls: ['../styles/detail-view.scss'],
46	    imports: [
47	        ContentHeroComponent,
48	        MatIcon,
49	        PortalInlinePlayerComponent,
50	        SafePipe,
51	        TranslatePipe,
52	    ],
53	})
