1	import {
2	    Component,
3	    OnDestroy,
4	    computed,
5	    effect,
6	    inject,
7	    input,
8	    output,
9	    signal,
10	} from '@angular/core';
11	import { MatSnackBar } from '@angular/material/snack-bar';
12	import { Router } from '@angular/router';
13	import { TranslatePipe, TranslateService } from '@ngx-translate/core';
14	import { FavoritesButtonComponent } from '../stalker-favorites-button/stalker-favorites-button.component';
15	import {
16	    ContentHeroComponent,
17	    SeasonContainerComponent,
18	    SeasonContainerPlaybackToggleRequest,
19	} from 'components';
20	import {
21	    PlaybackPositionData,
22	    ResolvedPortalPlayback,
23	    XtreamSerieEpisode,
24	} from 'shared-interfaces';
25	import {
26	    PORTAL_EXTERNAL_PLAYBACK,
27	    PORTAL_PLAYBACK_POSITIONS,
28	    PORTAL_PLAYER,
29	    createLogger,
30	    getStalkerReturnToState,
31	} from '@iptvnator/portal/shared/util';
32	import {
33	    getVodSeriesSeasonKey,
34	    isVodSeriesItem,
35	    mapRegularSeriesEpisodes,
36	    mapRegularSeriesSeasons,
37	    mapVodSeriesEpisodes,
38	    mapVodSeriesSeasonsToVm,
39	    StalkerMappedEpisode,
40	    StalkerSeriesSeasonVm,
41	    VodSeriesSeasonVm,
42	    normalizeStalkerVodDetailsItem,
43	    StalkerSelectedVodItem,
44	    StalkerStore,
45	    StalkerVodSource,
46	} from '@iptvnator/portal/stalker/data-access';
47	import { PortalInlinePlayerComponent } from '@iptvnator/ui/playback';
48	import { DownloadsService } from 'services';
49	
50	/**
51	 * Component for displaying series/episodes for Stalker portal content.
52	 * Supports three modes:
53	 * 1. Regular series (type=series): Fetches seasons from API via serialSeasonsResource
54	 * 2. VOD with embedded series (vclub): Uses the series array from the vodWithSeries input
55	 * 3. VOD series (Ministra is_series=1): Fetches seasons/episodes using movie_id and season_id
56	 */
57	@Component({
58	    selector: 'app-stalker-series-view',
59	    templateUrl: './stalker-series-view.component.html',
60	    styleUrls: ['../styles/detail-view.scss'],
61	    imports: [
62	        FavoritesButtonComponent,
63	        ContentHeroComponent,
64	        PortalInlinePlayerComponent,
65	        TranslatePipe,
66	        SeasonContainerComponent,
67	    ],
68	})
69	export class StalkerSeriesViewComponent implements OnDestroy {
70	    readonly stalkerStore = inject(StalkerStore);
71	    private readonly playbackPositions = inject(PORTAL_PLAYBACK_POSITIONS);
72	    private readonly portalPlayer = inject(PORTAL_PLAYER);
73	    private readonly router = inject(Router);
74	    private readonly externalPlayback = inject(PORTAL_EXTERNAL_PLAYBACK);
75	    private readonly downloadsService = inject(DownloadsService);
76	    private readonly snackBar = inject(MatSnackBar);
77	    private readonly translateService = inject(TranslateService);
78	    readonly backClicked = output<void>();
79	    private readonly logger = createLogger('StalkerSeriesView');
80	    readonly inlinePlayback = signal<ResolvedPortalPlayback | null>(null);
81	    readonly episodePlaybackPositions = signal<
82	        Map<number, PlaybackPositionData>
83	    >(new Map());
84	    private lastSaveTime = 0;
85	    private unsubscribePositionUpdates: (() => void) | null = null;
86	    readonly openingEpisodeId = signal<number | null>(null);
87	    readonly activeEpisodeId = signal<number | null>(null);
88	
89	    /**
90	     * Optional input for VOD items with embedded series array (vclub mode)
91	     * When provided, uses this instead of fetching seasons from API
92	     */
93	    readonly vodWithSeries = input<StalkerVodSource | null>(null);
94	
95	    readonly selectedItem = this.stalkerStore.selectedItem;
96	
97	    /**
98	     * Track VOD series seasons with their loaded episodes
99	     */
100	    readonly vodSeriesSeasons = signal<VodSeriesSeasonVm[]>([]);
101	
102	    /**
103	     * Indicates if this is a VOD series item (Ministra is_series=1)
104	     * Note: is_series can be true, 1, or "1" depending on the source
105	     */
106	    readonly isVodSeries = computed(() => {
107	        return (
108	            this.stalkerStore.selectedContentType() === 'vod' &&
109	            isVodSeriesItem(this.displayItem())
110	        );
111	    });
112	
113	    /**
114	     * Loading state for VOD series seasons
115	     */
116	    readonly isVodSeriesSeasonsLoading =
117	        this.stalkerStore.isVodSeriesSeasonsLoading;
118	
119	    /**
120	     * Loading state for regular series seasons
121	     */
122	    readonly isSerialSeasonsLoading = this.stalkerStore.isSerialSeasonsLoading;
123	
124	    constructor() {
125	        // Effect to load VOD series seasons when a VOD series item is selected
126	        effect(() => {
127	            if (this.isVodSeries()) {
128	                // Get seasons from the resource
129	                const seasons = this.stalkerStore.getVodSeriesSeasonsResource();
130	                this.vodSeriesSeasons.set(mapVodSeriesSeasonsToVm(seasons));
131	            } else {
132	                this.vodSeriesSeasons.set([]);
133	            }
134	        });
135	
136	        // Effect to load playback positions for Stalker series
137	        effect(() => {
138	            const item = this.displayItem();
139	            const playlist = this.stalkerStore.currentPlaylist();
140	            if (item && playlist?._id) {
141	                const normalizedSeriesId = this.toSeriesId(item.id);
142	                this.logger.debug(
143	                    'Loading positions for series',
144	                    {
145	                        id: item.id,
146	                        seriesId: normalizedSeriesId,
147	                        isSeries: item.is_series,
148	                    }
149	                );
150	                if (!isNaN(normalizedSeriesId)) {
151	                    void this.loadSeriesPositions(
152	                        playlist._id,
153	                        normalizedSeriesId
154	                    );
155	                }
156	            } else {
157	                this.episodePlaybackPositions.set(new Map());
158	            }
159	        });
160	
161	        effect(() => {
162	            const session = this.externalPlayback.activeSession();
163	            const item = this.displayItem();
164	            const playlistId = this.stalkerStore.currentPlaylist()?._id;
165	            const seriesId = item ? this.toSeriesId(item.id) : 0;
166	
167	            if (
168	                !session?.contentInfo ||
169	                !playlistId ||
170	                !seriesId ||
171	                session.contentInfo.contentType !== 'episode' ||
172	                session.contentInfo.playlistId !== playlistId ||
173	                session.contentInfo.seriesXtreamId !== seriesId
174	            ) {
175	                this.openingEpisodeId.set(null);
176	                this.activeEpisodeId.set(null);
177	                return;
178	            }
179	
180	            if (session.status === 'launching') {
181	                this.openingEpisodeId.set(session.contentInfo.contentXtreamId);
182	                this.activeEpisodeId.set(null);
183	                return;
184	            }
185	
186	            if (session.status === 'opened' || session.status === 'playing') {
187	                this.openingEpisodeId.set(null);
188	                this.activeEpisodeId.set(session.contentInfo.contentXtreamId);
189	                return;
190	            }
191	
192	            this.openingEpisodeId.set(null);
193	            this.activeEpisodeId.set(null);
194	        });
195	
196	        if (window.electron?.onPlaybackPositionUpdate) {
197	            this.unsubscribePositionUpdates =
198	                window.electron.onPlaybackPositionUpdate(
199	                    (data: PlaybackPositionData) => {
200	                        const playlistId =
201	                            this.stalkerStore.currentPlaylist()?._id;
202	                        const item = this.displayItem();
203	                        const seriesId = item ? this.toSeriesId(item.id) : 0;
204	
205	                        if (
206	                            data.contentType !== 'episode' ||
207	                            data.playlistId !== playlistId ||
208	                            data.seriesXtreamId !== seriesId
209	                        ) {
210	                            return;
211	                        }
212	
213	                        this.updateEpisodePlaybackPosition(data);
214	                    }
215	                );
216	        }
217	    }
218	
219	    /**
220	     * For VOD with embedded series, we create a single "season" with the episodes
221	     * For regular series, we use the API-fetched seasons
222	     */
223	    readonly regularSeasons = computed<StalkerSeriesSeasonVm[]>(() =>
224	        mapRegularSeriesSeasons(
225	            this.vodWithSeries(),
226	            this.stalkerStore.getSerialSeasonsResource()
227	        )
228	    );
229	
230	    /**
231	     * Get the item to display details for (either vodWithSeries or selectedItem from store)
232	     */
233	    readonly displayItem = computed<StalkerSelectedVodItem | null>(() => {
234	        const item = this.vodWithSeries() || this.selectedItem();
235	        return item ? normalizeStalkerVodDetailsItem(item) : null;
236	    });
237	
238	    /**
239	     * Adapts both Regular and VOD series data into the format expected by SeasonContainerComponent.
240	     * Record<string, XtreamSerieEpisode[]> where string is season number/name.
241	     */
242	    readonly mappedSeasons = computed<Record<string, XtreamSerieEpisode[]>>(
243	        () => {
244	            if (this.isVodSeries()) {
245	                return mapVodSeriesEpisodes(
246	                    this.vodSeriesSeasons(),
247	                    this.displayItem()?.info?.movie_image
248	                );
249	            }
250	
251	            return mapRegularSeriesEpisodes(
252	                this.regularSeasons(),
253	                this.displayItem()?.info?.movie_image
254	            );
255	        }
256	    );
257	
258	    /**
259	     * Handles season selection from the container.
260	     * For VOD Series, triggers lazy loading of episodes.
261	     */
262	    onSeasonSelected(seasonKey: string) {
263	        if (!this.isVodSeries()) return;
264	
265	        const seasons = this.vodSeriesSeasons();
266	        const season = seasons.find(
267	            (s) => getVodSeriesSeasonKey(s) === seasonKey
268	        );
269	
270	        if (season && season.episodes.length === 0) {
271	            this.loadEpisodesForSeason(season);
272	        }
273	    }
274	
275	    /**
276	     * Loads episodes for a specific VOD season
277	     */
278	    async loadEpisodesForSeason(season: VodSeriesSeasonVm) {
279	        // Set loading state in local signal
280	        const seasons = this.vodSeriesSeasons();
281	        const index = seasons.findIndex((s) => s.id === season.id);
282	        if (index === -1) return;
283	
284	        const updatedSeasons = [...seasons];
285	        updatedSeasons[index] = { ...updatedSeasons[index], isLoading: true };
286	        this.vodSeriesSeasons.set(updatedSeasons);
287	
288	        try {
289	            const episodes = await this.stalkerStore.fetchVodSeriesEpisodes(
290	                season.video_id,
291	                season.id
292	            );
293	
294	            // Update with loaded episodes
295	            const newSeasons = [...this.vodSeriesSeasons()];
296	            const newIndex = newSeasons.findIndex((s) => s.id === season.id);
297	            if (newIndex !== -1) {
298	                newSeasons[newIndex] = {
299	                    ...newSeasons[newIndex],
300	                    episodes: episodes,
301	                    isLoading: false,
302	                };
303	                this.vodSeriesSeasons.set(newSeasons);
304	            }
305	        } catch (error) {
306	            this.logger.error('Failed to load episodes', error);
307	            const newSeasons = [...this.vodSeriesSeasons()];
308	            const newIndex = newSeasons.findIndex((s) => s.id === season.id);
309	            if (newIndex !== -1) {
310	                newSeasons[newIndex] = {
311	                    ...newSeasons[newIndex],
312	                    isLoading: false,
313	                };
314	                this.vodSeriesSeasons.set(newSeasons);
315	            }
316	        }
317	    }
318	
319	    /**
320	     * Determines if the current selected season is loading
321	     */
322	    isCurrentSeasonLoading(seasonKey: string): boolean {
323	        if (!this.isVodSeries()) return false;
324	        const season = this.vodSeriesSeasons().find(
325	            (s) => getVodSeriesSeasonKey(s) === seasonKey
326	        );
327	        return season?.isLoading ?? false;
328	    }
329	
330	    /**
331	     * Handles episode click from the container
332	     */
333	    onEpisodeClicked(episode: XtreamSerieEpisode) {
334	        const mappedEpisode = episode as StalkerMappedEpisode;
335	
336	        if (mappedEpisode.custom_sid === 'vod-series') {
337	            // It's a VOD series episode (is_series=1 mode)
338	            // Use originalId for playback URL, but use generated id for tracking
339	            this.playVodSeriesEpisode({
340	                originalId: mappedEpisode.originalId, // For constructing playback URL
341	                trackingId: episode.id, // The generated unique ID for position tracking
342	                name: episode.title,
343	                series_number: episode.episode_num,
344	            });
345	        } else {
346	            // Regular series or vclub mode (VOD with embedded series array)
347	            // Use originalCmd for playback, episode.id for tracking
348	            const trackingId = Number(episode.id);
349	            this.playEpisodeClicked(
350	                episode.episode_num,
351	                mappedEpisode.originalCmd,
352	                trackingId
353	            );
354	        }
355	    }
356	
357	    /**
358	     * Play episode - handles regular series and vclub mode
359	     */
360	    playEpisodeClicked(episodeNum: number, cmd?: string, trackingId?: number) {
361	        const item = this.displayItem();
362	        if (!item) return;
363	        this.logger.debug('playEpisodeClicked', {
364	            episodeNum,
365	            cmd,
366	            trackingId,
367	            seriesId: item.id,
368	        });
369	
370	        const position = trackingId
371	            ? this.episodePlaybackPositions().get(trackingId)
372	            : undefined;
373	        const startTime = position?.positionSeconds;
374	        void this.startPlayback(
375	            cmd,
376	            item.info.name,
377	            item.info.movie_image,
378	            episodeNum,
379	            trackingId,
380	            startTime
381	        );
382	    }
383	
384	    /**
385	     * Play VOD series episode
386	     */
387	    playVodSeriesEpisode(episode: {
388	        originalId?: string;
389	        trackingId: string;
390	        name: string;
391	        series_number: number;
392	    }) {
393	        const item = this.displayItem();
394	        if (!item) return;
395	        // Use originalId for playback URL (this is what the Stalker API expects)
396	        const cmd = `/media/file_${episode.originalId ?? ''}.mpg`;
397	        const episodeName = episode.name || `Episode ${episode.series_number}`;
398	        // Use trackingId (generated unique ID) for playback position tracking
399	        const trackingId = Number(episode.trackingId);
400	
401	        this.logger.debug('playVodSeriesEpisode', {
402	            originalId: episode.originalId,
403	            trackingId,
404	            seriesId: item.id,
405	            episodeName,
406	        });
407	
408	        const position = this.episodePlaybackPositions().get(trackingId);
409	        const startTime = position?.positionSeconds;
410	        void this.startPlayback(
411	            cmd,
412	            `${item.info.name} - ${episodeName}`,
413	            item.info.movie_image,
414	            episode.series_number,
415	            trackingId,
416	            startTime
417	        );
418	    }
419	
420	    goBack() {
421	        const returnTo = getStalkerReturnToState(window.history.state);
422	        this.closeInlinePlayer();
423	        this.backClicked.emit();
424	        this.stalkerStore.clearSelectedItem();
425	
426	        if (returnTo) {
427	            void this.router.navigateByUrl(returnTo);
428	        }
429	    }
430	
431	    toSeriesId(id: string | number): number {
432	        const raw = String(id ?? '').trim();
433	        if (!raw) return 0;
434	        const primary = raw.includes(':') ? raw.split(':')[0] : raw;
435	        const parsed = Number(primary);
436	        return Number.isFinite(parsed) ? parsed : 0;
437	    }
438	
439	    closeInlinePlayer(): void {
440	        this.inlinePlayback.set(null);
441	        this.lastSaveTime = 0;
442	    }
443	
444	    handleInlineTimeUpdate(event: {
445	        currentTime: number;
446	        duration: number;
447	    }): void {
448	        const playback = this.inlinePlayback();
449	        if (!playback?.contentInfo) return;
450	
451	        const now = Date.now();
452	        if (now - this.lastSaveTime <= 15000) return;
453	
454	        this.lastSaveTime = now;
455	        const position: PlaybackPositionData = {
456	            ...playback.contentInfo,
457	            positionSeconds: Math.floor(event.currentTime),
458	            durationSeconds: Math.floor(event.duration),
459	        };
460	        void this.playbackPositions.savePlaybackPosition(
461	            playback.contentInfo.playlistId,
462	            position
463	        );
464	        this.updateEpisodePlaybackPosition(position);
465	    }
466	
467	    showCopyNotification(): void {
468	        this.snackBar.open(
469	            this.translateService.instant('PORTALS.STREAM_URL_COPIED'),
470	            null,
471	            {
472	                duration: 2000,
473	            }
474	        );
475	    }
476	
477	    private async startPlayback(
478	        cmd?: string,
479	        title?: string,
480	        thumbnail?: string,
481	        episodeNum?: number,
482	        episodeId?: number,
483	        startTime?: number
484	    ): Promise<void> {
485	        try {
486	            const playback = await this.stalkerStore.resolveVodPlayback(
487	                cmd,
488	                title,
489	                thumbnail,
490	                episodeNum,
491	                episodeId,
492	                startTime
493	            );
494	
495	            this.lastSaveTime = 0;
496	            if (this.portalPlayer.isEmbeddedPlayer()) {
497	                this.inlinePlayback.set(playback);
498	                return;
499	            }
500	
501	            this.closeInlinePlayer();
502	            void this.portalPlayer.openResolvedPlayback(playback, true);
503	        } catch (error) {
504	            this.logger.error('Failed to start inline series playback', error);
505	            const errorMessage =
506	                error instanceof Error &&
507	                error.message === 'nothing_to_play'
508	                    ? this.translateService.instant(
509	                          'PORTALS.CONTENT_NOT_AVAILABLE'
510	                      )
511	                    : this.translateService.instant('PORTALS.PLAYBACK_ERROR');
512	            this.snackBar.open(errorMessage, null, {
513	                duration: 3000,
514	            });
515	        }
516	    }
517	
518	    ngOnDestroy(): void {
519	        this.unsubscribePositionUpdates?.();
520	    }
521	
522	    async handlePlaybackToggleRequested(
523	        request: SeasonContainerPlaybackToggleRequest
524	    ): Promise<void> {
525	        const playlistId = this.stalkerStore.currentPlaylist()?._id;
526	        if (!playlistId) {
527	            return;
528	        }
529	
530	        if (request.nextPosition) {
531	            await this.playbackPositions.savePlaybackPosition(
532	                playlistId,
533	                request.nextPosition
534	            );
535	            this.updateEpisodePlaybackPosition(request.nextPosition);
536	            return;
537	        }
538	
539	        await this.playbackPositions.clearPlaybackPosition(
540	            playlistId,
541	            request.contentXtreamId,
542	            'episode'
543	        );
544	        this.removeEpisodePlaybackPosition(request.contentXtreamId);
545	    }
546	
547	    async downloadEpisode(episode: XtreamSerieEpisode): Promise<void> {
548	        const playlist = this.stalkerStore.currentPlaylist();
549	        const item = this.displayItem();
550	
551	        if (!playlist || !playlist.portalUrl || !playlist.macAddress || !item) {
552	            return;
553	        }
554	
555	        const customSid = (episode as { custom_sid?: string }).custom_sid;
556	        const cmd =
557	            customSid === 'vod-series'
558	                ? `/media/file_${(episode as { originalId?: string }).originalId}.mpg`
559	                : ((episode as { originalCmd?: string }).originalCmd ?? '');
560	
561	        let url: string;
562	        try {
563	            url = await this.stalkerStore.fetchLinkToPlay(
564	                playlist.portalUrl,
565	                playlist.macAddress,
566	                cmd,
567	                episode.episode_num
568	            );
569	            if (!url) {
570	                this.logger.error('Failed to resolve Stalker stream URL');
571	                return;
572	            }
573	        } catch (error) {
574	            this.logger.error('Error resolving Stalker stream URL', error);
575	            return;
576	        }
577	
578	        const episodeInfo = this.getEpisodeInfo(episode);
579	        const posterUrl = episodeInfo?.movie_image;
580	        const seasonNum = Number(episode.season || 1);
581	        const episodeNum = episode.episode_num || 1;
582	        const seriesTitle = item.info?.name || this.displayItem()?.info?.name || 'Series';
583	        const episodeTitle = `${seriesTitle} - S${String(seasonNum).padStart(
584	            2,
585	            '0'
586	        )}E${String(episodeNum).padStart(2, '0')} - ${episode.title}`;
587	
588	        await this.downloadsService.startDownload({
589	            playlistId: playlist._id,
590	            xtreamId: this.getEpisodeDownloadId(episode),
591	            contentType: 'episode',
592	            title: episodeTitle,
593	            url,
594	            posterUrl,
595	            seriesXtreamId: this.toSeriesId(item.id),
596	            seasonNumber: seasonNum,
597	            episodeNumber: episodeNum,
598	            headers: {
599	                userAgent: playlist.userAgent,
600	                referer: playlist.referrer,
601	                origin: playlist.origin,
602	            },
603	            playlistName: playlist.title || 'Stalker Portal',
604	            playlistType: 'stalker',
605	            portalUrl: playlist.portalUrl,
606	            macAddress: playlist.macAddress,
607	        });
608	    }
609	
610	    private async loadSeriesPositions(
611	        playlistId: string,
612	        seriesXtreamId: number
613	    ): Promise<void> {
614	        const positions = await this.playbackPositions.getSeriesPlaybackPositions(
615	            playlistId,
616	            seriesXtreamId
617	        );
618	        const positionsMap = new Map<number, PlaybackPositionData>();
619	        positions.forEach((position) => {
620	            positionsMap.set(position.contentXtreamId, position);
621	        });
622	        this.episodePlaybackPositions.set(positionsMap);
623	    }
624	
625	    private updateEpisodePlaybackPosition(position: PlaybackPositionData): void {
626	        const updated = new Map(this.episodePlaybackPositions());
627	        updated.set(position.contentXtreamId, position);
628	        this.episodePlaybackPositions.set(updated);
629	    }
630	
631	    private removeEpisodePlaybackPosition(contentXtreamId: number): void {
632	        const updated = new Map(this.episodePlaybackPositions());
633	        updated.delete(contentXtreamId);
634	        this.episodePlaybackPositions.set(updated);
635	    }
636	
637	    private getEpisodeInfo(
638	        episode: XtreamSerieEpisode
639	    ): { movie_image?: string } | undefined {
640	        if (!episode.info || Array.isArray(episode.info)) {
641	            return undefined;
642	        }
643	        return episode.info as { movie_image?: string };
644	    }
645	
646	    private getEpisodeDownloadId(episode: XtreamSerieEpisode): number {
647	        const customSid = (episode as { custom_sid?: string }).custom_sid;
648	
649	        if (customSid === 'regular-series') {
650	            const cmd = (episode as { originalCmd?: string }).originalCmd;
651	            if (cmd) {
652	                const match = cmd.match(/file_(\d+)/);
653	                if (match) {
654	                    return Number(match[1]);
655	                }
656	                return this.hashString(cmd);
657	            }
658	            return Number(episode.id);
659	        }
660	
661	        if (customSid === 'vod-series') {
662	            const originalId = (episode as { originalId?: string | number })
663	                .originalId;
664	            const numericId = Number(originalId);
665	            return Number.isNaN(numericId)
666	                ? this.hashString(String(originalId))
667	                : numericId;
668	        }
669	
670	        const numericId = Number(episode.id);
671	        return Number.isNaN(numericId)
672	            ? this.hashString(String(episode.id))
673	            : numericId;
674	    }
675	
676	    private hashString(str: string): number {
677	        let hash = 0;
678	        for (let index = 0; index < str.length; index++) {
679	            const char = str.charCodeAt(index);
680	            hash = (hash << 5) - hash + char;
681	            hash &= hash;
682	        }
683	        return Math.abs(hash);
684	    }
685	}
