// ----------------------------------------------------------------------------
// Secondary action buttons — unified geometry with .play-btn, translucent glass
// surface. State (active favorite, downloaded, downloading) is expressed via
// icon + subtle accent ring, not full-surface color swaps.
// ----------------------------------------------------------------------------
.favorite-btn,
.download-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 22px;
    min-height: 54px;
    font-size: 0.9375rem;
    font-weight: 600;
    letter-spacing: 0.01em;
    background: var(--action-secondary-bg);
    color: var(--action-secondary-fg);
    border: 1px solid var(--action-secondary-border);
    border-radius: 14px;
    cursor: pointer;
    transition:
        background-color 200ms ease,
        border-color 200ms ease,
        box-shadow 200ms ease,
        transform 200ms cubic-bezier(0.22, 1, 0.36, 1);

    &:hover:not(:disabled) {
        background: var(--action-secondary-bg-hover);
        transform: translateY(-1px);
    }

    &:active:not(:disabled) {
        transform: translateY(0);
    }

    &:focus-visible {
        outline: 2px solid var(--accent-color);
        outline-offset: 3px;
    }

    mat-icon {
        font-size: 22px;
        width: 22px;
        height: 22px;
        transition: color 200ms ease;
    }
}

.favorite-btn {
    &--active {
        box-shadow: inset 0 0 0 1.5px var(--action-accent-ring);

        mat-icon {
            color: var(--accent-color);
        }
    }
}

.download-btn {
    &--completed mat-icon {
        color: var(--action-success-icon);
    }

    &--downloading {
        cursor: progress;
        opacity: 0.85;

        mat-icon {
            animation: downloadingSpin 1.8s linear infinite;
        }
    }
}

@keyframes downloadingSpin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

