        @if (meta.ratingKinopoisk) {
            <div class="details__meta-item">
                <span class="label">{{ 'XTREAM.KINOPOISK_RATING' | translate }}</span>
                <span class="value">{{ meta.ratingKinopoisk }}</span>
            </div>
        }
    </ng-container>

    <!-- Action Buttons -->
    <ng-container hero-actions>
        <!-- Resume/Play buttons -->
        @if (hasPlaybackPosition()) {
            <button
                class="play-btn play-btn--resume"
                (click)="onPrimaryAction()"
                [disabled]="isExternalLaunchPending()"
                [class.play-btn--state-launching]="externalPrimaryButtonState() === 'launching'"
                [class.play-btn--state-stop]="externalPrimaryButtonState() === 'stop'"
            >
                <span class="play-btn__icon-shell" aria-hidden="true">
                    <mat-icon class="play-btn__icon">{{ externalPrimaryIcon() }}</mat-icon>
                </span>
                <span class="play-btn__label" aria-live="polite">
                    @if (externalPrimaryLabel(); as label) {
                        {{ label }}
                    } @else {
                        {{ 'XTREAM.RESUME' | translate }} {{ formattedPosition() }}
                    }
                </span>
            </button>
            @if (!isExternalStopAction()) {
                <button class="play-btn play-btn--restart" (click)="onPlay()">
                    <mat-icon>replay</mat-icon>
                    {{ 'XTREAM.RESTART' | translate }}
                </button>
            }
        } @else {
            <button
                class="play-btn"
                (click)="onPrimaryAction()"
                [disabled]="isExternalLaunchPending()"
                [class.play-btn--state-launching]="externalPrimaryButtonState() === 'launching'"
                [class.play-btn--state-stop]="externalPrimaryButtonState() === 'stop'"
            >
                <span class="play-btn__icon-shell" aria-hidden="true">
                    <mat-icon class="play-btn__icon">{{ externalPrimaryIcon() }}</mat-icon>
                </span>
                <span class="play-btn__label" aria-live="polite">
                    @if (externalPrimaryLabel(); as label) {
                        {{ label }}
                    } @else {
                        {{ 'XTREAM.PLAY' | translate }}
                    }
                </span>
            </button>
        }

        <!-- Favorites button -->
        @if (!isFavorite()) {
            <button
                class="favorite-btn"
                type="button"
                [attr.aria-pressed]="false"
                [attr.aria-label]="'PORTALS.ADD_TO_FAVORITES' | translate"
                (click)="toggleFavorite()"
            >
                <mat-icon>favorite_border</mat-icon>
                {{ 'PORTALS.ADD_TO_FAVORITES' | translate }}
            </button>
        } @else {
            <button
                class="favorite-btn favorite-btn--active"
                type="button"
                [attr.aria-pressed]="true"
                [attr.aria-label]="'PORTALS.REMOVE_FROM_FAVORITES' | translate"
                (click)="toggleFavorite()"
            >
                <mat-icon>favorite</mat-icon>
                {{ 'PORTALS.REMOVE_FROM_FAVORITES' | translate }}
            </button>
        }

        <!-- Download buttons (Electron only) -->
        @if (isElectron()) {
            @if (isDownloaded()) {
                <button
                    class="download-btn download-btn--completed"
                    type="button"
                    [attr.aria-label]="'DOWNLOADS.PLAY_LOCAL' | translate"
                    (click)="playFromLocal()"
                >
                    <mat-icon>play_circle</mat-icon>
                    {{ 'DOWNLOADS.PLAY_LOCAL' | translate }}
                </button>
            } @else if (isDownloading()) {
                <button
                    class="download-btn download-btn--downloading"
                    type="button"
                    [attr.aria-label]="'DOWNLOADS.STATUS.DOWNLOADING' | translate"
                    disabled
                >
                    <mat-icon>downloading</mat-icon>
                    {{ 'DOWNLOADS.STATUS.DOWNLOADING' | translate }}
                </button>
            } @else {
                <button
                    class="download-btn"
                    type="button"
                    [attr.aria-label]="'DOWNLOADS.DOWNLOAD' | translate"
                    (click)="onDownload()"
                >
                    <mat-icon>download</mat-icon>
                    {{ 'DOWNLOADS.DOWNLOAD' | translate }}
                </button>
            }
        }
    </ng-container>

    @if (inlinePlayback(); as playback) {
        <app-portal-inline-player
            [playback]="playback"
            (timeUpdate)="onInlineTimeUpdate($event)"
            (closed)="closeInlinePlayback()"
            (streamUrlCopied)="onStreamUrlCopied()"
        />
    }

    <!-- YouTube Trailer (Xtream only) -->
    @if (meta.youtubeTrailer) {
        <div class="youtube-trailer">
            <h3>{{ 'XTREAM.YOUTUBE_TRAILER' | translate }}</h3>
            <div class="trailer-wrapper">
                <iframe
                    [src]="'https://www.youtube.com/embed/' + meta.youtubeTrailer | safe"
                    title="YouTube video player"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                    referrerpolicy="strict-origin-when-cross-origin"
                    allowfullscreen
                ></iframe>
            </div>
        </div>
    }
</app-content-hero>

