readonly openingEpisodeId = signal<number | null>(null);
readonly activeEpisodeId = signal<number | null>(null);

/**
 * Picks the next episode to play: first in-progress episode (position > 0
 * and > 30s remaining), else the very first episode of the earliest season.
 */
readonly nextEpisodeInfo = computed<{
    episode: XtreamSerieEpisode;
    position: number;
    isResume: boolean;
} | null>(() => {
    const item = this.selectedItem();
    if (!item?.episodes) return null;

    const orderedSeasons = Object.keys(item.episodes).sort(
        (a, b) => Number(a) - Number(b)
    );
    const positions = this.episodePlaybackPositions();

    for (const key of orderedSeasons) {
        const episodes = [...(item.episodes[key] ?? [])].sort(
            (a, b) => Number(a.episode_num) - Number(b.episode_num)
        );
        for (const ep of episodes) {
            const pos = positions.get(Number(ep.id));
            if (
                pos &&
                pos.positionSeconds > 0 &&
                (pos.durationSeconds === 0 ||
                    pos.durationSeconds - pos.positionSeconds > 30)
            ) {
                return {
                    episode: ep,
                    position: pos.positionSeconds,
                    isResume: true,
                };
            }
        }
    }

    for (const key of orderedSeasons) {
        const episodes = [...(item.episodes[key] ?? [])].sort(
            (a, b) => Number(a.episode_num) - Number(b.episode_num)
        );
        if (episodes.length > 0) {
            return { episode: episodes[0], position: 0, isResume: false };
        }
    }

    return null;
});

readonly nextEpisodeLabel = computed(() => {
    const info = this.nextEpisodeInfo();
    if (!info) return '';
    const s = String(info.episode.season).padStart(2, '0');
    const e = String(info.episode.episode_num).padStart(2, '0');
    const key = info.isResume ? 'XTREAM.RESUME' : 'XTREAM.PLAY';
    return `${this.translateService.instant(key)} S${s}·E${e}`;
});

