    }
}

// ============================================================================
// Seasons & Episodes - Inside details section
// ============================================================================

.seasons {
    margin-top: 24px;
    width: 100%;

    .season-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 12px 0;
        cursor: pointer;
        transition: opacity 0.2s ease;

        &:hover {
            opacity: 0.8;
        }

        h4 {
            margin: 0;
            font-size: 1rem;
            font-weight: 600;
        }

        .expand-icon {
            font-size: 0.75rem;
            color: var(--text-muted);
        }
    }

    .episodes {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
        padding: 8px 0 16px;

        button {
            margin: 0;
            font-weight: 500;
        }
    }

    .episodes-loading,
    .seasons-loading {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 20px 0;
        color: var(--text-secondary);
    }

    .no-episodes {
        color: var(--text-muted);
        font-style: italic;
        padding: 8px 0;
    }
}

// Seasons loading when inside details
.details .seasons-loading {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 20px 0;
    color: var(--text-secondary);
    margin-top: 24px;
}

// Season container when inside details section
.details app-season-container {
